import math

class Solution:
    def minOperations(self, k: int) -> int:
        ans = k - 1
        limit = int(math.isqrt(k)) + 2
        for x in range(1, limit + 1):
            copies = (k + x - 1) // x
            ops = (x - 1) + (copies - 1)
            if ops < ans:
                ans = ops
        return ans

class Solution {
public:
    int minOperations(int k) {
        int ans = k - 1;
        int limit = sqrt(k) + 2;
        for (int x = 1; x <= limit; ++x) {
            int copies = (k + x - 1) / x;
            int ops = (x - 1) + (copies - 1);
            ans = min(ans, ops);
        }
        return ans;
    }
};

class Solution {
    public int minOperations(int k) {
        int ans = k - 1;
        int limit = (int) Math.sqrt(k) + 2;
        for (int x = 1; x <= limit; x++) {
            int copies = (k + x - 1) / x;
            int ops = (x - 1) + (copies - 1);
            ans = Math.min(ans, ops);
        }
        return ans;
    }
}

var minOperations = function(k) {
    let ans = k - 1;
    const limit = Math.floor(Math.sqrt(k)) + 2;
    for (let x = 1; x <= limit; x++) {
        const copies = Math.ceil(k / x);
        const ops = (x - 1) + (copies - 1);
        if (ops < ans) {
            ans = ops;
        }
    }
    return ans;
};
